formulas.expression:
() => {

	for (const item of previewItems) {

		gsap.set(item.DOM.imageInner, {transformOrigin: '50% 0%'});

		item.scrollTimeline = gsap.timeline({
			scrollTrigger: {
				trigger: item.DOM.el,
				start: 'top bottom',
				end: 'bottom top',
				scrub: true
			}
		})
		.addLabel('start', 0)
		.to(item.DOM.title, {
			ease: 'none',
			yPercent: -100
		}, 'start')
		.to(item.DOM.imageInner, {
			ease: 'none',
			scaleY: 1.8,
		}, 'start')

	}

}

