formulas.expression:
item => {
	let arr = [];
	for (const [position, otherItem] of previewItems.entries()) {

		if ( item != otherItem && isInViewport(otherItem.DOM.el) ) {
			arr.push({position: position, item: otherItem});
		}

	}
	return arr;
}

