formulas.expression:
() => {
	for (const [pos,item] of previewItems.entries()) {
		item.DOM.imageWrap.addEventListener('click', () => {
			if ( isAnimating ) return;
			isAnimating = true;
			currentItem = pos;
			showContent(item);
		});
	}

	backCtrl.addEventListener('click', () => {
		if ( isAnimating ) return;
		isAnimating = true;
		hideContent();
	});
}

